filament_guide.scad_template:
// Parametric Filament Guide Clip
// The clip's cross-section -- C-clip around the extrusion, side
// entry opening with snap lips, guide arm with a teardrop tube
// hole -- is one 2D profile extruded to the clip width.  Prints
// flat with no supports; layer lines wrap the C so the snap flexes
// along the plastic, not across layers.
es = ${extrusion_size};
tid = ${tube_id};
al = ${arm_length};
wall = ${wall};

clip_w = 15;
arm_w = tid + wall * 2;
// Tube hole center, up the arm from the top of the clip body
hole_y = es + wall * 2 + al - arm_w / 2;

module teardrop(d) {
    // Circle plus a 45-degree roof so the horizontal hole prints
    // cleanly without support
    r = d / 2;
    circle(r = r, $fn = 30);
    polygon([[-r * 0.707, r * 0.707], [0, r * 1.414],
             [r * 0.707, r * 0.707]]);
}

module profile() {
    difference() {
        union() {
            // Clip body around the extrusion
            square([es + wall * 2, es + wall * 2]);
            // Guide arm rising from the top, with a rounded end
            translate([es / 2 + wall - arm_w / 2, es + wall * 2 - 0.1])
                square([arm_w, al - arm_w / 2 + 0.1]);
            translate([es / 2 + wall, hole_y])
                circle(d = arm_w, $fn = 30);
        }
        // Extrusion pocket
        translate([wall, wall])
            square([es + 0.5, es + 0.5]);
        // Side entry opening with snap lips (clips onto the rail)
        translate([-0.1, wall + es * 0.15])
            square([wall + 0.2, es * 0.7]);
        // Tube hole
        translate([es / 2 + wall, hole_y])
            teardrop(tid);
    }
}

linear_extrude(clip_w) profile();

nozzle_rack.scad_template:
// Parametric Nozzle Rack
