spacing = nd + wall;
total_w = n * spacing + wall;
total_d = nd + wall * 2;
base_h = 3;

module rack() {
    difference() {
        cube([total_w, total_d, depth + base_h]);
        for (i = [0:n-1]) {
            translate([wall + i * spacing + nd/2, total_d/2, base_h])
                cylinder(h=depth + 1, d=nd + 0.3, $fn=6);
        }
    }
}

