seed_spacer.scad_template:
// Parametric Seed Spacer
gs = ${grid_spacing};
cols = ${cols};
rows = ${rows};
hd = ${hole_dia};
t = ${thickness};

margin = 10;
total_w = (cols - 1) * gs + margin * 2;
total_d = (rows - 1) * gs + margin * 2;

module spacer() {
    difference() {
        cube([total_w, total_d, t]);
        for (c = [0:cols-1])
            for (r = [0:rows-1])
                translate([margin + c * gs, margin + r * gs, -0.1])
                    cylinder(h=t+0.2, d=hd, $fn=20);
