phone_vent_mount.scad_template:
// Parametric Phone Vent Mount
// Two flat parts, both printed without supports.  The cradle prints
// on its back (grips and ledge rise as walls); the vent fin prints
// on its side.  The fin's tongue slides through the slot in the
// cradle's plate until its flange seats, then the tongue hooks
// behind a vent slat -- the vent face traps the plate against the
// flange, and the phone's weight keeps the hook seated.
pw = ${phone_width};
gd = ${grip_depth};
vsw = ${vent_slot_width};
t = ${thickness};

body_h = 40;
tongue_len = 28;
fin_t = 9;                 // fin thickness (across the slot)
tongue_h = max(1.8, vsw * 0.9);
hook_drop = 3;

module cradle() {
    difference() {
        union() {
            // Back plate on the bed
            cube([pw + gd * 2, body_h, t]);
            // Side grips
            for (x = [0, pw + gd])
                translate([x, 0, 0])
                    cube([gd, body_h, gd]);
            // Bottom ledge (holds the phone's lower edge)
            translate([gd, 0, 0])
                cube([pw, t, gd * 0.6]);
        }
        // Fin slot through the plate
        translate([(pw + gd * 2 - fin_t - 0.4) / 2, body_h * 0.55, -0.1])
            cube([fin_t + 0.4, tongue_h + 0.4, t + 0.2]);
    }
}

module fin() {
    x0 = 4;                          // flange thickness
    x1 = x0 + t + 0.6 + tongue_len;  // tongue end / hook face
    linear_extrude(fin_t)
        polygon([
            [0, -4],                          // flange bottom
            [x0, -4],
            [x0, 0],                          // tongue underside
            [x1, 0],
            [x1, -hook_drop],                 // hook face (catches slat)
            [x1 + 1.5, -hook_drop],           // hook bottom
            [x1 + 1.5 + hook_drop + tongue_h, tongue_h],  // entry ramp
            [x0, tongue_h],                   // tongue top edge
            [x0, tongue_h + 4],               // flange top
            [0, tongue_h + 4],
        ]);
}

cradle();
// Fin printed beside the cradle, flat on its side
translate([(pw + gd * 2) / 2 + fin_t / 2, body_h + 8, 0])
    rotate([0, 0, 90])
        fin();

fuse_puller.scad_template:
// Parametric Fuse Puller
l = ${length};
fw = ${fuse_width};
t = ${thickness};

handle_w = 15;
tip_gap = fw + 1;

module puller() {
    // Left arm
    hull() {
        cube([handle_w/2, t, l * 0.6]);
        translate([-tip_gap/2 + handle_w/4, 0, l - 8])
            cube([3, t, 8]);
    }
    // Right arm
    hull() {
        translate([handle_w/2, 0, 0])
            cube([handle_w/2, t, l * 0.6]);
        translate([tip_gap/2 + handle_w/4 - 3 + handle_w/2, 0, l - 8])
            cube([3, t, 8]);
    }
    // Bridge at base
    cube([handle_w, t, 5]);
    // Grip ridges
    for (z = [10:8:l*0.5]) {
        translate([0, t, z])
            cube([handle_w, 1, 2]);
    }
}

puller();

corner_clamp_jig.scad_template:
// 90-Degree Corner Clamp Jig
al = ${arm_length};
aw = ${arm_width};
h = ${height};
t = ${thickness};

module jig() {
    // Inner corner block
    cube([aw, aw, h]);
    // Arm 1 (X direction)
    cube([al, t, h]);
    // Arm 2 (Y direction)
    cube([t, al, h]);
    // Base plate
    cube([al, al, t]);
    // Diagonal brace
    translate([aw, aw, 0])
        linear_extrude(height=t)
