bench_dog.scad_template:
// Parametric Bench Dog
// Prints head-down: the wide head is on the bed, a 45-degree cone
// flares out to the shoulder, and the peg rises last.  The
// shoulder's seating face (which registers on the bench top in use)
// prints as a flat top surface.
hd = ${hole_dia};
ph = ${peg_height};
pd = ${peg_depth};
head = ${head_dia};

spring_cut = 1;
head_d = head * 0.8;
cone_h = (head - head_d) / 2 * 1.1;

module dog() {
    difference() {
        union() {
            // Above-surface head (on the bed)
            cylinder(h = ph - 3, d = head_d, $fn = 40);
            // Printable cone out to the shoulder
            translate([0, 0, ph - 3])
                cylinder(h = cone_h, d1 = head_d, d2 = head, $fn = 40);
            // Shoulder; its top face seats on the bench in use
            translate([0, 0, ph - 3 + cone_h])
                cylinder(h = 3, d = head, $fn = 40);
            // Below-surface peg
            translate([0, 0, ph + cone_h])
                cylinder(h = pd, d = hd - 0.5, $fn = 40);
        }
        // Spring slot for friction fit, cut down from the peg tip
        translate([-spring_cut / 2, -hd / 2, ph + cone_h + pd * 0.3])
            cube([spring_cut, hd, pd + 0.1]);
    }
}

dog();

hose_barb_adapter.scad_template:
// Parametric Hose Barb Adapter
// The whole body is one revolved profile (and the bore another), so
// there are no stacked-solid seams to leave artifacts.  Barbs are
// symmetric ~40-degree diamonds: printable without supports in
// either direction, and the ridge still bites under a hose clamp.
sid = ${small_id};
lid = ${large_id};
bl = ${barb_length};
wall = ${wall};

barb_h = 1.2;   // radial ridge height
barbs = 3;
step = bl / barbs;
// ~40 degrees on each barb face, capped so short barb sections
// keep a monotonic profile
rise = min(barb_h * 2 * 1.2, step * 0.45);
sod = sid + wall * 2;
lod = lid + wall * 2;
shoulder_d = max(sid, lid) + wall * 2 + barb_h * 2;
cone_h = (shoulder_d - sod) / 2 * 1.1;   // 45-degree cone under shoulder
z_top = bl + cone_h + 4;                 // large section start

// One barbed section as revolved-profile points, base at z0
function barb_pts(od, z0) = concat(
    [[od / 2, z0]],
    [for (i = [0:barbs - 1]) each [
        [od / 2, z0 + i * step + step - 2 * rise],
        [od / 2 + barb_h, z0 + i * step + step - rise],
        [od / 2, z0 + (i + 1) * step]]]);

module adapter() {
    difference() {
        rotate_extrude($fn = 60)
            polygon(concat(
                [[0, 0]],
                barb_pts(sod, 0),
                [[shoulder_d / 2, bl + cone_h],
                 [shoulder_d / 2, z_top]],
                barb_pts(lod, z_top),
                [[0, z_top + bl]]));
        // Bore: small end, 45-degree internal transition, large end
        rotate_extrude($fn = 60)
            polygon([[0, -0.1],
                     [sid / 2, -0.1],
                     [sid / 2, z_top - (lid - sid) / 2 * 1.1],
                     [lid / 2, z_top],
                     [lid / 2, z_top + bl + 0.1],
                     [0, z_top + bl + 0.1]]);
    }
}

adapter();

drain_strainer.scad_template:
// Parametric Drain Strainer
// The recessed disc sits in the drain; a 45-degree cone joins it to
// the rim, so the rim underside prints without supports and the
// strainer self-centers in the drain.
dd = ${drain_dia};
rim = ${rim_width};
slots = ${slot_count};
t = ${thickness};

od = dd + rim * 2;
slot_w = 2;
cone_h = (od - (dd - 1)) / 2 * 1.1;  // slightly steeper than 45

module strainer() {
    difference() {
        union() {
            // Recessed disc that sits inside the drain
            cylinder(h = 3, d = dd - 1, $fn = 60);
            // Printable cone transition out to the rim
            translate([0, 0, 3])
                cylinder(h = cone_h, d1 = dd - 1, d2 = od, $fn = 60);
            // Rim
            translate([0, 0, 3 + cone_h])
                cylinder(h = t, d = od, $fn = 60);
        }
        // Radial slots, kept inside the recessed disc.  The inner
        // start radius grows with slot count so neighboring slots
        // never merge near the center.
        slot_r0 = max(5, slots * slot_w / 6.28 * 1.3);
        for (a = [0:360 / slots:359]) {
            rotate([0, 0, a])
                translate([-slot_w / 2, slot_r0, -0.1])
                    cube([slot_w, max(2, dd / 2 - 3 - slot_r0),
                          3 + cone_h + t + 0.2]);
        }
        // Center hole
        translate([0, 0, -0.1])
            cylinder(h = 3 + cone_h + t + 0.2, d = 8, $fn = 20);
    }
}

strainer();

raspberry_pi_case.scad_template:
// Parametric RPi Case
// Two parts printed side by side, both open-face-up so neither has
// an unsupported ceiling.  Flip the lid over onto the base to close.
// Mounting standoffs follow the official Pi mechanical drawing:
// 58 x 49 mm hole pattern, 3.5 mm from the SD-card end and 3.5 mm
// from each long edge.
bw = ${board_width};
bd = ${board_depth};
bh = ${board_height};
wall = ${wall};
vents = ${vent_slots};

clear = 1;
ow = bw + clear * 2 + wall * 2;
od = bd + clear * 2 + wall * 2;
oh = bh + wall * 2 + 3;
// Official hole pattern (85x56 board): inset 3.5 from the SD end,
// spans 58 along the board; 3.5 from each long edge, spanning 49.
hole_span_y = 58;
hole_inset = 3.5;

module standoff() {
    difference() {
        cylinder(h = 3, d = 6, $fn = 20);
        translate([0, 0, -0.1])
            cylinder(h = 3.2, d = 2.7, $fn = 20);
    }
}

module case_bottom() {
    difference() {
        cube([ow, od, oh / 2]);
        translate([wall, wall, wall])
            cube([bw + clear * 2, bd + clear * 2, oh]);
        // Power / HDMI cutout (long side)
        translate([ow - wall - 0.1, wall + clear + 5, wall + 3])
            cube([wall + 0.2, 45, oh]);
        // SD card slot (short side, SD end); 45-degree peaked top
        // so the wall above it prints without a bridge
        translate([wall + bw / 2 - 6, -0.1, wall])
            cube([12, wall + 0.2, 3]);
        translate([wall + bw / 2, wall + 0.1, wall + 3])
            rotate([90, 0, 0])
                linear_extrude(wall + 0.2)
                    polygon([[-6, 0], [6, 0], [0, 6]]);
        // USB / Ethernet opening (short side opposite the SD end),
        // open through the top edge
        translate([wall + clear + 2, od - wall - 0.1, wall + 2])
            cube([bw - 4, wall + 0.2, oh]);
        // Ventilation: slots run through the top (mating) edge so
        // they print without ceilings
        if (vents == 1) {
            for (y = [wall + 5 : 4 : od - wall - 5]) {
                translate([-0.1, y, wall + 2])
                    cube([wall + 0.2, 2, oh / 2]);
            }
        }
    }
    // PCB standoffs on the official hole pattern
    for (x = [wall + clear + hole_inset, wall + clear + bw - hole_inset])
        for (y = [wall + clear + hole_inset,
                  wall + clear + min(hole_inset + hole_span_y,
                                     bd - hole_inset)])
            translate([x, y, wall])
                standoff();
}

module case_top() {
    // Printed roof-down (open face up); flip over onto the base.
    translate([ow + 10, 0, 0]) {
        difference() {
            cube([ow, od, oh / 2]);
            translate([wall, wall, wall])
                cube([bw + clear * 2, bd + clear * 2, oh / 2]);
            // USB / Ethernet notch: printed y-min wall lands on the
            // USB face when the lid is flipped over onto the base
            translate([wall + clear + 2, -0.1, oh / 2 - 10])
                cube([bw - 4, wall + 0.2, 10.1]);
        }
    }
}

case_bottom();
case_top();

switch_panel.scad_template:
