        difference() {
            cylinder(h=w, r=8+t, $fn=30);
            translate([0, 0, -0.1])
                cylinder(h=w+0.2, r=8, $fn=30);
            translate([-20, -20, -0.1])
                cube([40, 20, w+0.2]);
        }
}

