cable_chain_link.scad_template:
// Cable Chain Link
// Open-top U-channel that actually admits a cable, with pivot pins
// on the male end and a widened female mouth with pin holes on the
// other.  Links snap together end to end.  Prints floor-down with
// no sealed cavities.
iw = ${inner_width};
ih = ${inner_height};
ll = ${link_length};
wall = ${wall};
pd = ${pin_dia};

ow = iw + wall * 2;
oh = ih + wall;                // floor + open top
mouth = pd * 2 + 4;            // overlap length at the joint
pz = wall + ih * 0.5;          // pivot height

module link() {
    difference() {
        union() {
            // Channel: floor and side walls, open top
            cube([ll, ow, wall]);
            for (s = [0, ow - wall])
                translate([0, s, 0])
                    cube([ll - mouth, wall, oh]);
            // Female mouth: walls spread outward so the next link's
            // male end nests inside
            for (s = [-wall - 0.3, ow + 0.3])
                translate([ll - mouth, s, 0])
                    cube([mouth, wall, oh]);
            // Ribs joining the channel walls to the offset mouth walls
            for (s = [-wall - 0.3, ow - wall])
                translate([ll - mouth, s, 0])
                    cube([wall, wall * 2 + 0.3, oh]);
            // Pivot pins on the male end, sticking outward
            for (s = [0, ow])
                translate([mouth / 2, s + (s == 0 ? -wall * 0.7 : 0), pz])
                    rotate([-90, 0, 0])
                        cylinder(h = wall * 0.7, d = pd, $fn = 20);
        }
        // Pin holes through the female mouth walls
        for (s = [-wall - 0.4, ow + 0.3 - 0.1])
            translate([ll - mouth / 2, s, pz])
                rotate([-90, 0, 0])
                    cylinder(h = wall + 0.2, d = pd + 0.4, $fn = 20);
        // Chamfer the male end's top edge so the joint can pivot
        translate([-0.1, -wall - 0.5, pz + pd / 2 + 1])
            rotate([0, -30, 0])
                cube([mouth * 2, ow + wall * 2 + 1, oh]);
    }
}

link();

cable_wrap_guide.scad_template:
// Cable Wrap Guide
// Two parts printed side by side: the spool body (bottom flange +
// hub) and a separate top flange disc.  The mounting screw passes
// through both and clamps the flange on when the spool is mounted;
// a shallow boss on the hub locates the flange concentrically.
sd = ${spool_dia};
sw = ${spool_width};
cs = ${cable_slot};
wall = ${wall};
mh = ${mount_holes};

hub_d = sd / 3;
boss_h = 1.6;

module spool_body() {
    difference() {
        union() {
            // Bottom flange
            cylinder(h = wall, d = sd, $fn = 50);
            // Hub; the top 1.6 mm acts as a locating boss for the
            // top flange
            cylinder(h = wall + sw + boss_h, d = hub_d, $fn = 40);
        }
        // Center screw hole
        translate([0, 0, -0.1])
            cylinder(h = wall + sw + boss_h + 0.2, d = mh, $fn = 20);
        // Cable entry slot through hub and flange
        translate([0, -cs / 2, -0.1])
            cube([sd / 2 + 1, cs, wall + sw + boss_h + 0.2]);
    }
}

module top_flange() {
    difference() {
        cylinder(h = wall + boss_h, d = sd, $fn = 50);
        // Locating recess that drops over the hub boss
        translate([0, 0, wall])
            cylinder(h = boss_h + 0.1, d = hub_d + 0.4, $fn = 40);
        // Center screw hole
        translate([0, 0, -0.1])
            cylinder(h = wall + boss_h + 0.2, d = mh, $fn = 20);
    }
}

spool_body();
translate([sd + 10, 0, 0])
    top_flange();

clamp_pad.scad_template:
// Soft Jaw Clamp Pad
// Prints face-down: the pad face lies flat on the bed and the
// wrap-around grips rise as vertical walls.  No supports.
jw = ${jaw_width};
jh = ${jaw_height};
d = ${depth};
t = ${thickness};

module pad() {
    // Pad face on the bed
    cube([jw, jh, t]);
    // Wrap-around grips (top and bottom edges of the jaw)
    translate([0, 0, t])
        cube([jw, t, d - t]);
    translate([0, jh - t, t])
        cube([jw, t, d - t]);
    // Side retainers
    translate([0, 0, t])
        cube([t, jh, d - t]);
    translate([jw - t, 0, t])
        cube([t, jh, d - t]);
}

pad();

dowel_jig.scad_template:
// Dowel Jig
dd = ${dowel_dia};
nh = ${holes};
sp = ${spacing};
bw = ${body_width};
gd = ${guide_depth};

bl = (nh - 1) * sp + bw;

module jig() {
    difference() {
        // Main body
        cube([bl, bw, gd]);
        // Guide holes
        for (i = [0:nh-1])
            translate([bw/2 + i * sp, bw/2, -0.1])
                cylinder(h=gd+0.2, d=dd, $fn=30);
        // Reference edge groove
        translate([-0.1, bw-2, gd/2])
            cube([bl+0.2, 2.1, gd/2+0.1]);
    }
}

jig();

birdhouse_panel.scad_template:
// Birdhouse Front Panel
// Prints flat on its back: the panel is a 2D outline extruded to
// thickness, and the perch is a vertical post fused to the panel.
w = ${width};
h = ${height};
ed = ${entry_dia};
t = ${thickness};
pd = ${perch_dia};

module panel() {
    difference() {
        // Panel with peaked top, lying flat
        linear_extrude(t)
            polygon([[0, 0], [w, 0], [w, h - w / 4],
                     [w / 2, h], [0, h - w / 4]]);
        // Entry hole
        translate([w / 2, h * 0.6, -0.1])
            cylinder(h = t + 0.2, d = ed, $fn = 40);
    }
    // Perch: vertical post fused to the panel front
    translate([w / 2, h * 0.6 - ed / 2 - 15, 0])
        cylinder(h = t + 15, d = pd, $fn = 20);
}

panel();

gear_spur.scad_template:
// Parametric Spur Gear
n = ${teeth};
m = ${module_mm};
fw = ${face_width};
bd = ${bore_dia};
pa = ${pressure_angle};

pitch_r = n * m / 2;
outer_r = pitch_r + m;
root_r = pitch_r - 1.25 * m;

module tooth() {
    tw = m * 3.14159 / 2;
    polygon([
        [root_r, -tw/2],
        [outer_r - 0.2, -tw/3],
        [outer_r, 0],
        [outer_r - 0.2, tw/3],
        [root_r, tw/2]
    ]);
}

module gear() {
    difference() {
        linear_extrude(height=fw) {
            difference() {
                circle(r=outer_r + 0.1, $fn=n*4);
                circle(r=root_r, $fn=n*4);
            }
            circle(r=root_r, $fn=n*4);
            for (i = [0:n-1])
                rotate([0, 0, i * 360/n])
                    tooth();
        }
        // Center bore
        translate([0, 0, -0.1])
            cylinder(h=fw+0.2, d=bd, $fn=30);
    }
}

gear();

pulley_gt2.scad_template:
// GT2 Timing Pulley
nt = ${teeth};
bd = ${bore_dia};
bw = ${belt_width};
fd = ${flange_dia};

pitch = 2; // GT2 = 2mm pitch
pr = nt * pitch / (2 * 3.14159);
or = pr + 0.25;
// Flanges must clear the tooth barrel or the barrel overhangs them
fde = max(fd, (or + 1.5) * 2);
fh = 1.5; // flange height
// 45-degree cone joining the barrel to the top flange, so the
// flange underside prints without supports
cone_h = max(0.6, (fde / 2 - or) * 1.1);

module pulley() {
    difference() {
        union() {
            // Bottom flange
            cylinder(h = fh, d = fde, $fn = 50);
            // Toothed section
            translate([0, 0, fh])
                cylinder(h = bw, r = or, $fn = nt * 2);
            // Printable cone up to the top flange
            translate([0, 0, fh + bw])
                cylinder(h = cone_h, r1 = or, r2 = fde / 2, $fn = 50);
            // Top flange
            translate([0, 0, fh + bw + cone_h])
                cylinder(h = fh, d = fde, $fn = 50);
        }
        // Bore
        translate([0, 0, -0.1])
            cylinder(h = bw + fh * 2 + cone_h + 0.2, d = bd, $fn = 30);
        // Teeth grooves (simplified)
        for (i = [0:nt - 1])
            rotate([0, 0, i * 360 / nt])
                translate([pr, 0, fh - 0.1])
                    cylinder(h = bw + 0.2, d = 1, $fn = 10);
    }
}

pulley();

z_axis_guide.scad_template:
// Z-Axis Endstop Mount
sw = ${slot_width};
mh = ${mount_height};
eshw = ${switch_width};
t = ${thickness};

module mount() {
    difference() {
        union() {
            // Clamp body
            cube([20 + t*2, t, mh]);
            // Switch platform
            translate([20 + t*2, 0, 0])
                cube([eshw + t*2, t + 12, t]);
        }
        // Extrusion slot
        translate([t + (20 - sw)/2, -0.1, mh/2 - 5])
            cube([sw, t + 0.2, 10]);
        // Switch mounting holes
        for (dx = [t + 4, t + eshw - 2])
            translate([20 + t*2 + dx, t + 6, -0.1])
                cylinder(h=t+0.2, d=2.5, $fn=15);
    }
}

mount();

tool_holder_pegboard.scad_template:
// Pegboard Tool Holder
// Prints in its use orientation, flat on the bed.  Horizontal
// members are cylinders trimmed with a flat bottom at the 45-degree
// tangent, so they sit on the bed and print without supports while
// still fitting round pegboard holes.
hl = ${hook_length};
hd = ${hook_dia};
ps = ${peg_spacing};
np = ${pegs};

peg_d = hd - 0.5;
// Drop the axis so the widest remaining under-curve is 45 degrees
peg_z = peg_d / 2 * 0.707;
arm_z = hd / 2 * 0.707;

// Horizontal cylinder along +X with a flat bottom on the bed
module flat_bottom_rod(len, d, axis_z) {
    difference() {
        translate([0, 0, axis_z])
            rotate([0, 90, 0])
                cylinder(h = len, d = d, $fn = 30);
        translate([-0.1, -d, -d])
            cube([len + 0.2, d * 2, d]);
    }
}

module holder() {
    bar_len = (np - 1) * ps + hd;
    for (i = [0:np - 1])
        translate([0, i * ps, 0]) {
            // Peg (into the board), rooted in the bar
            translate([-0.5, 0, 0])
                flat_bottom_rod(15.5, peg_d, peg_z);
            // Upward pin at the bar for hanging small tools
            translate([-hd / 2, 0, 0])
                cylinder(h = hd + 10, d = hd, $fn = 20);
        }
    // Connecting bar, its back face against the board
    translate([-hd, -hd / 2, 0])
        cube([hd, bar_len, hd]);
    // Hook arm reaching away from the board, rooted in the bar
    translate([-hd - hl, ((np - 1) * ps) / 2, 0])
        flat_bottom_rod(hl + 1, hd, arm_z);
    // Hook tip (upward) to retain the hung tool
    translate([-hd - hl + hd / 2, ((np - 1) * ps) / 2, 0])
        cylinder(h = 15, d = hd, $fn = 20);
}

holder();

fridge_magnet.scad_template:
// Fridge Magnet — rectangle, square, circle, or oval
w = ${width};
h = ${height};
t = ${thickness};
md = ${magnet_diameter};
mz = ${magnet_depth};
shape = "${shape}";

$fn = 80;

module magnet_body() {
    if (shape == "circle")
        cylinder(d=w, h=t);
    else if (shape == "oval")
        scale([1, h/w, 1]) cylinder(d=w, h=t);
    else if (shape == "square") {
        r = 3;
        hull() {
            translate([r,r,0]) cylinder(r=r, h=t, $fn=20);
            translate([w-r,r,0]) cylinder(r=r, h=t, $fn=20);
            translate([w-r,w-r,0]) cylinder(r=r, h=t, $fn=20);
            translate([r,w-r,0]) cylinder(r=r, h=t, $fn=20);
        }
    } else {
        // rectangle (default)
        r = 3;
        hull() {
            translate([r,r,0]) cylinder(r=r, h=t, $fn=20);
            translate([w-r,r,0]) cylinder(r=r, h=t, $fn=20);
            translate([w-r,h-r,0]) cylinder(r=r, h=t, $fn=20);
            translate([r,h-r,0]) cylinder(r=r, h=t, $fn=20);
        }
    }
}

difference() {
    magnet_body();
    // Magnet recess on back — centered
    cx = (shape == "circle" || shape == "oval") ? 0 : (shape == "square" ? w/2 : w/2);
    cy = (shape == "circle" || shape == "oval") ? 0 : (shape == "square" ? w/2 : h/2);
    translate([cx, cy, -0.1])
        cylinder(d=md+0.3, h=mz+0.1, $fn=40);
}

bookmark.scad_template:
// Parametric Bookmark
w = ${width};
l = ${length};
t = ${thickness};
cd = ${clip_depth};

module bookmark() {
    // Main body with rounded top
    hull() {
        cube([w, l - w/2, t]);
        translate([w/2, l - w/2, 0])
            cylinder(d=w, h=t, $fn=40);
    }
    // Page clip (hook at bottom)
    if (cd > 0) {
        translate([w*0.2, -cd, 0])
            cube([w*0.6, cd, t]);
        translate([w*0.2, -cd, 0])
            cube([w*0.6, t*2, t + 3]);
    }
}

bookmark();

pen_cup.scad_template:
// Pen Cup — cylinder or rectangle with QR pocket on bottom
shape = "${shape}";
d = ${diameter};
dp = ${depth};
h = ${height};
wt = ${wall_thickness};
bt = ${bottom_thickness};
cr = ${corner_radius};
qr_size = ${qr_pocket_size};
qr_depth = ${qr_pocket_depth};

$fn = 180;

module outer_shell() {
    if (shape == "rectangle") {
        hull() {
            translate([cr,cr,0]) cylinder(r=cr, h=h);
            translate([d-cr,cr,0]) cylinder(r=cr, h=h);
            translate([d-cr,dp-cr,0]) cylinder(r=cr, h=h);
            translate([cr,dp-cr,0]) cylinder(r=cr, h=h);
        }
    } else {
        cylinder(d=d, h=h);
    }
}

module inner_cavity() {
    if (shape == "rectangle") {
        translate([wt, wt, bt])
            hull() {
                r = max(1, cr - wt);
                translate([r,r,0]) cylinder(r=r, h=h);
                translate([d-2*wt-r,r,0]) cylinder(r=r, h=h);
                translate([d-2*wt-r,dp-2*wt-r,0]) cylinder(r=r, h=h);
                translate([r,dp-2*wt-r,0]) cylinder(r=r, h=h);
            }
    } else {
        translate([0, 0, bt])
            cylinder(d=d - 2*wt, h=h);
    }
}

module qr_pocket() {
    if (qr_size > 0) {
        cx = (shape == "rectangle") ? d/2 : 0;
        cy = (shape == "rectangle") ? dp/2 : 0;
        translate([cx - qr_size/2, cy - qr_size/2, -0.01])
            cube([qr_size, qr_size, qr_depth + 0.01]);
    }
}

difference() {
    outer_shell();
    inner_cavity();
    qr_pocket();
}
